import{_ as d,b as l,c as i,d as a,t as v,C as n,u as o}from"./index-I5uTs6b4.js";const p={class:"level-page"},u={class:"level-content"},r={class:"level-title"},h={__name:"Level49",props:{id:{type:String,required:!0}},setup(e){const s=o();function c(){sessionStorage.setItem("skipIntro","1"),s.push("/")}return(_,t)=>(l(),i("div",p,[a("button",{class:"back-btn",onClick:c},"← Back to Index"),a("div",u,[a("h1",r,"SI-"+v(e.id),1),t[0]||(t[0]=n('<p class="level-name" data-v-0c5ae251>&quot;暴雨&quot;</p><div class="section" data-v-0c5ae251><h2 data-v-0c5ae251>生存难度：等级 3</h2><div class="difficulty" data-v-0c5ae251><ul class="class-list" data-v-0c5ae251><li data-v-0c5ae251><span class="class-bullet unsafe" data-v-0c5ae251></span> 不安全</li><li data-v-0c5ae251><span class="class-bullet unstable" data-v-0c5ae251></span> 不稳定</li><li data-v-0c5ae251><span class="class-bullet entity" data-v-0c5ae251></span> 特殊实体</li></ul></div></div><div class="section" data-v-0c5ae251><h2 data-v-0c5ae251>描述</h2><p data-v-0c5ae251>该层级表现为一座类伦敦风格的城市，大小无法估量，其中建筑与变异生态形成共生关系。整座城市呈现出一种诡异的生命力，空气中弥漫着潮湿的植物腥气，混合着麦芽发酵味。部分路面覆盖着藤蔓与荧光菌毯。天空永远灰蒙蒙的，有时还会起大雾。建筑已经不再是单纯的无机物，与植物共生一体，成为了植物攀附生长的框架，而植物又弥合了建筑的伤痕。</p><p data-v-0c5ae251>该层级含有丰富的地下通道网络，主要为地下铁路网、特殊防核掩体和排水系统。</p><p data-v-0c5ae251>该层级会迎来周期性的大雨。起初的雨水细如牛毛，但在几秒内便会变为黄豆大小，随后降水量激增，雨水倾盆，好似海洋倒扣而下。流浪者甚至无法在雨中看清任何事物，甚至无法在雨水的压力下挪动身体。只有矗立在各处的巨大教堂与钟楼得以幸免——雨水甚至无法进入这两种建筑内，属于绝对安全区。地下只有防核掩体内不会进水。雨后，受损的建筑会被植物修复愈合。</p><p data-v-0c5ae251>某些钟楼和教堂的顶部高过云端。在这些建筑的顶部，你可以一窥云层之上的天空。白天，天上没有太阳，取而代之的是漆黑的月亮，其上却有着洁白的斑纹。夜间的月亮与正常月亮无异。下雨时云层之上会凝聚更高的一层黑云，风暴在两层云间肆虐，电闪雷鸣。</p></div><div class="section" data-v-0c5ae251><h2 data-v-0c5ae251>特殊实体</h2><div class="entity-box" data-v-0c5ae251><p class="entity-name" data-v-0c5ae251>&quot;线&quot;</p><p data-v-0c5ae251>该实体会在被大雨覆盖的区域出现，无法影响未损毁的建筑及其内部以及绝对安全区。线会随机切割空间，造成错位或空间的替换。在空间被切割前，被切割区域的边界会有约半秒左右的闪光出现。</p></div><div class="entity-box" data-v-0c5ae251><p class="entity-name" data-v-0c5ae251>&quot;气球&quot;</p><p data-v-0c5ae251>数量极其稀少，表现为普通的粉色充气气球。流浪者可通过给粉气球充气的方式切出该层级。如果粉气球充气爆炸前未能切出，将变为灰气球。灰气球被充气至爆炸后，会生成半径 527 米的降雨区并跟随流浪者移动，雨水会修复身体损伤。大雨持续九小时零八分钟，雨停之后流浪者将在一声钟声后化为玻璃破碎死亡。</p></div><div class="entity-box" data-v-0c5ae251><p class="entity-name" data-v-0c5ae251>&quot;奈落之底&quot;</p><p data-v-0c5ae251>一把英国韦伯利转轮手枪，装填六发子弹。该实体会使持有者性格阴暗面被放大。子弹具有必中效果（150 米内），但最后一发子弹绝对会以某种方式杀死持有者。使用灰气球后必中半径扩大到 486 米。可被带出层级。</p></div></div><div class="section" data-v-0c5ae251><h2 data-v-0c5ae251>入口与出口</h2><h3 class="sub-heading" data-v-0c5ae251>切入</h3><p data-v-0c5ae251>在狭窄通道中有概率出现切入点；在水中或雨中触碰闪白细线可切入。</p><h3 class="sub-heading" data-v-0c5ae251>切出</h3><ul class="entry-list" data-v-0c5ae251><li data-v-0c5ae251>从穿过云层的钟楼或教堂顶部跳下（有概率被重伤甚至杀死）</li><li data-v-0c5ae251>使用粉&quot;气球&quot;切出</li></ul></div>',5))])]))}},q=d(h,[["__scopeId","data-v-0c5ae251"]]);export{q as default};
